<div class="modal fade" id="planModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form id="planForm"><div class="modal-header"><div><h5 class="modal-title" id="planModalTitle">Nouveau plan de formation</h5><small class="text-muted">Un seul plan actif par campagne.</small></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf'])?>"><input type="hidden" name="id" id="planId"><div class="row g-3"><div class="col-12"><label class="form-label">Campagne *</label><select name="campaign_id" id="campaignId" class="form-select" required></select></div><div class="col-12"><label class="form-label">Référentiel pédagogique</label><select name="referential_id" id="referentialId" class="form-select"><option value="">Aucun / non applicable</option></select><small class="text-muted">Seuls les référentiels actifs compatibles avec le type de stage sont proposés.</small></div><div class="col-12"><label class="form-label">Titre *</label><input name="titre" id="planTitle" class="form-control" maxlength="200" required placeholder="Ex. Plan de formation clinique D4 2026"></div><div class="col-12"><label class="form-label">Description</label><textarea name="description" id="planDescription" class="form-control" rows="4" maxlength="3000"></textarea></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light border" data-bs-dismiss="modal">Annuler</button><button class="btn btn-primary-stagia" id="savePlanBtn"><i class="bi bi-check-lg me-1"></i> Enregistrer</button></div></form></div></div></div>

<div class="modal fade" id="itemsModal" tabindex="-1"><div class="modal-dialog modal-xl modal-dialog-centered"><div class="modal-content"><div class="modal-header"><div><h5 class="modal-title" id="itemsTitle">Contenu du plan</h5><small class="text-muted" id="itemsSub"></small></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="training-detail-head mb-3" id="planSummary"></div><div id="lockedNotice" class="locked-box d-none mb-3"><i class="bi bi-lock me-1"></i> Ce plan est publié ou archivé : son contenu est en lecture seule.</div><form id="itemForm" class="border rounded-3 p-3 mb-3"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf'])?>"><input type="hidden" name="id" id="itemId"><input type="hidden" name="plan_id" id="itemPlanId"><div class="row g-3"><div class="col-md-2"><label class="form-label">Ordre *</label><input type="number" min="1" name="ordre" id="itemOrder" class="form-control" value="1" required></div><div class="col-md-3"><label class="form-label">Type *</label><select name="type_item" id="itemType" class="form-select"><option value="MODULE">Module</option><option value="OBJECTIF">Objectif</option><option value="ACTIVITE" selected>Activité</option><option value="ETAPE">Étape</option></select></div><div class="col-md-7"><label class="form-label">Titre *</label><input name="titre" id="itemTitle" class="form-control" maxlength="200" required></div><div class="col-12 d-none" id="objectiveWrap"><div class="objective-box"><label class="form-label">Objectif du référentiel</label><select name="referential_objective_id" id="objectiveId" class="form-select"><option value="">Aucun lien</option></select></div></div><div class="col-12"><label class="form-label">Description</label><textarea name="description" id="itemDescription" class="form-control" rows="2" maxlength="3000"></textarea></div><div class="col-md-4" id="unitWrap"><label class="form-label">Service / unité</label><select name="host_unit_id" id="unitId" class="form-select"><option value="">Aucun / général</option></select></div><div class="col-md-4"><label class="form-label">Responsable</label><select name="responsible_user_id" id="responsibleId" class="form-select"><option value="">Non défini</option></select></div><div class="col-md-2"><label class="form-label">Début prévu</label><input type="date" name="date_debut_prevue" id="itemStart" class="form-control"></div><div class="col-md-2"><label class="form-label">Fin prévue</label><input type="date" name="date_fin_prevue" id="itemEnd" class="form-control"></div><div class="col-12 d-flex align-items-center justify-content-between"><div class="form-check"><input class="form-check-input" type="checkbox" name="obligatoire" id="itemRequired" value="1" checked><label class="form-check-label" for="itemRequired">Élément obligatoire</label></div><div class="d-flex gap-2"><button type="button" class="btn btn-light border d-none" id="cancelItemEdit">Annuler modification</button><button class="btn btn-primary-stagia" id="saveItemBtn"><i class="bi bi-plus-lg me-1"></i> Ajouter</button></div></div></div></form><div class="table-responsive"><table class="table stagia-modern-table align-middle mb-0"><thead><tr><th>#</th><th>TYPE / TITRE</th><th>LIENS</th><th>PÉRIODE</th><th>OBL.</th><th>STATUT</th><th class="text-end">ACTION</th></tr></thead><tbody id="itemRows"></tbody></table></div></div><div class="modal-footer"><button type="button" class="btn btn-light border" data-bs-dismiss="modal">Fermer</button></div></div></div></div>

<script>
document.addEventListener('DOMContentLoaded',()=>{
const BASE='<?=BASE_URL?>',$=id=>document.getElementById(id),esc=STAGIA.escape,planModal=new bootstrap.Modal($('planModal')),itemsModal=new bootstrap.Modal($('itemsModal'));let items=[],campaigns=[],refs=[],objectives=[],units=[],users=[],permissions={},currentPlan=null,timer;
const statusBadge=s=>({BROUILLON:['Brouillon','bg-secondary-subtle text-secondary'],PUBLIE:['Publié','bg-success-subtle text-success'],ARCHIVE:['Archivé','bg-dark-subtle text-dark']}[s]||[s,'bg-light text-dark']);
function render(){const q=$('search').value.trim().toLowerCase(),st=$('statusFilter').value,filtered=items.filter(x=>(!st||x.statut===st)&&(!q||[x.titre,x.description,x.campaign_title,x.campaign_code,x.stage_type_libelle,x.referential_label].join(' ').toLowerCase().includes(q)));$('rows').innerHTML=filtered.length?filtered.map(x=>{const b=statusBadge(x.statut),canEdit=permissions.update&&x.statut==='BROUILLON';return `<tr><td><strong>${esc(x.titre)}</strong><small class="d-block text-muted">${esc(x.description||'')}</small></td><td><strong>${esc(x.campaign_title)}</strong><small class="d-block text-muted">${esc(x.campaign_code||'—')} · ${esc(x.stage_type_libelle||'')}</small><small class="d-block text-muted">${esc(x.campaign_start)} → ${esc(x.campaign_end)}</small></td><td>${x.referential_id?`<strong>${esc(x.referential_code||'')}</strong><small class="d-block text-muted">${esc(x.referential_label||'')} ${esc(x.referential_version||'')}</small>`:'<span class="text-muted">Aucun</span>'}</td><td><strong>${Number(x.items_count)||0}</strong><small class="d-block text-muted">élément(s)</small></td><td><span class="badge ${b[1]}">${b[0]}</span></td><td class="text-end"><div class="btn-group btn-group-sm"><button class="btn btn-outline-dark content-btn" data-id="${x.id}" title="Contenu"><i class="bi bi-list-check"></i></button>${canEdit?`<button class="btn btn-outline-primary edit-plan" data-id="${x.id}" title="Modifier"><i class="bi bi-pencil"></i></button>`:''}${permissions.publish&&x.statut==='BROUILLON'?`<button class="btn btn-outline-success plan-status" data-id="${x.id}" data-action="PUBLISH" title="Publier"><i class="bi bi-send-check"></i></button>`:''}${permissions.publish&&x.statut!=='ARCHIVE'?`<button class="btn btn-outline-secondary plan-status" data-id="${x.id}" data-action="ARCHIVE" title="Archiver"><i class="bi bi-archive"></i></button>`:''}</div></td></tr>`}).join(''):'<tr><td colspan="6" class="text-center py-5 text-muted">Aucun plan de formation.</td></tr>';document.querySelectorAll('.content-btn').forEach(b=>b.onclick=()=>openItems(+b.dataset.id));document.querySelectorAll('.edit-plan').forEach(b=>b.onclick=()=>editPlan(+b.dataset.id));document.querySelectorAll('.plan-status').forEach(b=>b.onclick=()=>planStatus(+b.dataset.id,b.dataset.action));}
async function load(){try{const r=await STAGIA.request(BASE+'/actions/stages/training-plan-list.php');items=r.data.items||[];campaigns=r.data.campaigns||[];refs=r.data.referentials||[];objectives=r.data.objectives||[];units=r.data.units||[];users=r.data.users||[];permissions=r.data.permissions||{};const k=r.data.kpi||{};$('kTotal').textContent=k.total||0;$('kDraft').textContent=k.draft||0;$('kPublished').textContent=k.published||0;$('kArchived').textContent=k.archived||0;$('addPlanBtn').classList.toggle('d-none',!permissions.create);render();if(currentPlan){const id=currentPlan.id;currentPlan=items.find(x=>x.id===id)||null;if(currentPlan)renderItems();}}catch(e){STAGIA.toast(e.message,'danger');}}
function campaignOptions(selected=''){const used=new Set(items.filter(x=>x.statut!=='ARCHIVE'&&String(x.id)!==String($('planId').value)).map(x=>String(x.campaign_id)));$('campaignId').innerHTML='<option value="">Sélectionner une campagne...</option>'+campaigns.map(c=>`<option value="${c.id}" data-stage-type="${c.stage_type_id}" ${String(c.id)===String(selected)?'selected':''} ${used.has(String(c.id))?'disabled':''}>${esc(c.titre)} — ${esc(c.stage_type_libelle)} (${esc(c.type_campagne)})</option>`).join('');updateRefs();}
function updateRefs(selected=''){const c=campaigns.find(x=>String(x.id)===String($('campaignId').value)),sid=c?.stage_type_id;$('referentialId').innerHTML='<option value="">Aucun / non applicable</option>'+refs.filter(r=>!sid||r.stage_type_id===sid).map(r=>`<option value="${r.id}" ${String(r.id)===String(selected)?'selected':''}>${esc(r.code)} — ${esc(r.libelle)} ${esc(r.version||'')}</option>`).join('');}
function openCreate(){$('planForm').reset();$('planId').value='';$('planModalTitle').textContent='Nouveau plan de formation';campaignOptions();planModal.show();}
function editPlan(id){const x=items.find(v=>v.id===id);if(!x||x.statut!=='BROUILLON')return;$('planForm').reset();$('planId').value=x.id;$('planTitle').value=x.titre||'';$('planDescription').value=x.description||'';$('planModalTitle').textContent='Modifier le plan de formation';campaignOptions(x.campaign_id);updateRefs(x.referential_id||'');planModal.show();}
$('campaignId').onchange=()=>updateRefs();$('planForm').onsubmit=async e=>{e.preventDefault();STAGIA.loading($('savePlanBtn'),true);try{const url=$('planId').value?BASE+'/actions/stages/training-plan-update.php':BASE+'/actions/stages/training-plan-store.php',r=await STAGIA.post(url,new FormData(e.currentTarget));STAGIA.toast(r.message);planModal.hide();await load();}catch(e){STAGIA.toast(e.message,'danger');}finally{STAGIA.loading($('savePlanBtn'),false);}};
async function planStatus(id,action){const msg=action==='PUBLISH'?'Publier ce plan ? Après publication, son contenu sera verrouillé.':'Archiver ce plan de formation ?';if(!STAGIA.confirm(msg))return;const fd=new FormData();fd.append('csrf','<?=htmlspecialchars($_SESSION['csrf'])?>');fd.append('id',id);fd.append('action',action);try{const r=await STAGIA.post(BASE+'/actions/stages/training-plan-status.php',fd);STAGIA.toast(r.message);await load();}catch(e){STAGIA.toast(e.message,'danger');}}
function fillItemSelects(){const os=currentPlan?.referential_id?objectives.filter(o=>o.referential_id===currentPlan.referential_id):[];$('objectiveId').innerHTML='<option value="">Aucun lien</option>'+os.map(o=>`<option value="${o.id}">${esc(o.code||'')} ${esc(o.libelle)}</option>`).join('');$('objectiveWrap').classList.toggle('d-none',!os.length);$('unitId').innerHTML='<option value="">Aucun / général</option>'+units.map(u=>`<option value="${u.id}">${esc(u.nom)}${u.code?' — '+esc(u.code):''}</option>`).join('');$('unitWrap').classList.toggle('d-none',!units.length);$('responsibleId').innerHTML='<option value="">Non défini</option>'+users.map(u=>`<option value="${u.id}">${esc(u.nom_complet||'Utilisateur #'+u.id)}</option>`).join('');}
function resetItemForm(){$('itemForm').reset();$('itemId').value='';$('itemPlanId').value=currentPlan?.id||'';$('itemOrder').value=(currentPlan?.items?.length||0)+1;$('itemType').value='ACTIVITE';$('itemRequired').checked=true;$('cancelItemEdit').classList.add('d-none');$('saveItemBtn').innerHTML='<i class="bi bi-plus-lg me-1"></i> Ajouter';fillItemSelects();}
function renderItems(){if(!currentPlan)return;const locked=currentPlan.statut!=='BROUILLON'||!permissions.update;$('itemsTitle').textContent=currentPlan.titre;$('itemsSub').textContent=currentPlan.campaign_title+' · '+currentPlan.stage_type_libelle;$('planSummary').innerHTML=`<div class="row g-2"><div class="col-md-4"><small class="text-muted d-block">Campagne</small><strong>${esc(currentPlan.campaign_title)}</strong></div><div class="col-md-4"><small class="text-muted d-block">Référentiel</small><strong>${esc(currentPlan.referential_code||'Aucun')}</strong></div><div class="col-md-4"><small class="text-muted d-block">Période</small><strong>${esc(currentPlan.campaign_start)} → ${esc(currentPlan.campaign_end)}</strong></div></div>`;$('lockedNotice').classList.toggle('d-none',!locked);$('itemForm').classList.toggle('d-none',locked);fillItemSelects();const rows=currentPlan.items||[];$('itemRows').innerHTML=rows.length?rows.map(i=>`<tr class="${i.actif?'':'opacity-50'}"><td><strong>${i.ordre}</strong></td><td><span class="badge bg-light text-dark border item-type">${esc(i.type_item)}</span><strong class="d-block mt-1">${esc(i.titre)}</strong><small class="text-muted">${esc(i.description||'')}</small></td><td>${i.objective_label?`<small class="d-block"><i class="bi bi-bullseye me-1"></i>${esc(i.objective_label)}</small>`:''}${i.host_unit_name?`<small class="d-block"><i class="bi bi-geo-alt me-1"></i>${esc(i.host_unit_name)}</small>`:''}${i.responsible_name?`<small class="d-block"><i class="bi bi-person me-1"></i>${esc(i.responsible_name)}</small>`:''}${!i.objective_label&&!i.host_unit_name&&!i.responsible_name?'<span class="text-muted">—</span>':''}</td><td>${esc(i.date_debut_prevue||'—')} → ${esc(i.date_fin_prevue||'—')}</td><td>${i.obligatoire?'<span class="badge bg-primary-subtle text-primary">OUI</span>':'<span class="text-muted">Non</span>'}</td><td><span class="badge ${i.actif?'bg-success-subtle text-success':'bg-secondary-subtle text-secondary'}">${i.actif?'ACTIF':'INACTIF'}</span></td><td class="text-end">${!locked?`<div class="btn-group btn-group-sm"><button class="btn btn-outline-primary edit-item" data-id="${i.id}"><i class="bi bi-pencil"></i></button><button class="btn ${i.actif?'btn-outline-danger':'btn-outline-success'} item-status" data-id="${i.id}" data-action="${i.actif?'DISABLE':'RESTORE'}"><i class="bi ${i.actif?'bi-trash':'bi-arrow-counterclockwise'}"></i></button></div>`:'<span class="text-muted">Lecture seule</span>'}</td></tr>`).join(''):'<tr><td colspan="7" class="text-center py-4 text-muted">Aucun élément dans ce plan.</td></tr>';document.querySelectorAll('.edit-item').forEach(b=>b.onclick=()=>editItem(+b.dataset.id));document.querySelectorAll('.item-status').forEach(b=>b.onclick=()=>itemStatus(+b.dataset.id,b.dataset.action));}
function openItems(id){currentPlan=items.find(x=>x.id===id);if(!currentPlan)return;resetItemForm();renderItems();itemsModal.show();}
function editItem(id){const i=currentPlan?.items?.find(x=>x.id===id);if(!i)return;resetItemForm();$('itemId').value=i.id;$('itemOrder').value=i.ordre;$('itemType').value=i.type_item;$('itemTitle').value=i.titre||'';$('itemDescription').value=i.description||'';$('objectiveId').value=i.referential_objective_id||'';$('unitId').value=i.host_unit_id||'';$('responsibleId').value=i.responsible_user_id||'';$('itemStart').value=i.date_debut_prevue||'';$('itemEnd').value=i.date_fin_prevue||'';$('itemRequired').checked=!!i.obligatoire;$('cancelItemEdit').classList.remove('d-none');$('saveItemBtn').innerHTML='<i class="bi bi-check-lg me-1"></i> Modifier';}
$('cancelItemEdit').onclick=resetItemForm;$('objectiveId').onchange=()=>{const o=objectives.find(x=>String(x.id)===String($('objectiveId').value));if(o&&$('itemType').value==='OBJECTIF'){if(!$('itemTitle').value.trim())$('itemTitle').value=o.libelle||'';if(!$('itemDescription').value.trim())$('itemDescription').value=o.description||'';}};$('itemForm').onsubmit=async e=>{e.preventDefault();STAGIA.loading($('saveItemBtn'),true);try{const url=$('itemId').value?BASE+'/actions/stages/training-plan-item-update.php':BASE+'/actions/stages/training-plan-item-store.php',r=await STAGIA.post(url,new FormData(e.currentTarget));STAGIA.toast(r.message);await load();resetItemForm();}catch(e){STAGIA.toast(e.message,'danger');}finally{STAGIA.loading($('saveItemBtn'),false);}};
async function itemStatus(id,action){if(!STAGIA.confirm(action==='DISABLE'?'Retirer cet élément du plan ?':'Réactiver cet élément ?'))return;const fd=new FormData();fd.append('csrf','<?=htmlspecialchars($_SESSION['csrf'])?>');fd.append('id',id);fd.append('action',action);try{const r=await STAGIA.post(BASE+'/actions/stages/training-plan-item-status.php',fd);STAGIA.toast(r.message);await load();}catch(e){STAGIA.toast(e.message,'danger');}}
$('addPlanBtn').onclick=openCreate;$('refreshBtn').onclick=load;$('statusFilter').onchange=render;$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(render,200);};load();
});
</script>
